/**
 * Statement vault file handling: content sniffing, filename sanitising and
 * on-disk storage. Pure of HTTP and SQL so it can be tested on its own.
 *
 * Security rules, all enforced here:
 *  - the client's filename is display metadata only; the on-disk key is
 *    `<business uuid>/<document uuid>`, generated by the server;
 *  - keys are re-validated and the resolved path re-checked before any fs call;
 *  - the content type is decided from the bytes, never trusted from the client.
 */
import { createReadStream, type ReadStream } from "node:fs";
import { mkdir, open, rm, stat } from "node:fs/promises";
import { dirname, resolve, sep } from "node:path";
import type { StatementContentType } from "@riffle/db";

const KEY = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

const PNG = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

/**
 * Decide the type from the file's bytes. PDFs, PNGs and JPEGs are matched by
 * signature. CSV has no signature, so it must be well-formed UTF-8 text without
 * control characters (besides tab/CR/LF) and must not look like markup.
 */
export function detectContentType(buf: Buffer): StatementContentType | null {
  if (buf.length === 0) return null;
  // The PDF spec allows the header within the first 1024 bytes; we are stricter: it must lead.
  if (buf.subarray(0, 5).toString("latin1") === "%PDF-") return "application/pdf";
  if (buf.length >= PNG.length && buf.subarray(0, PNG.length).equals(PNG)) return "image/png";
  if (buf.length >= 3 && buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) return "image/jpeg";
  return looksLikeCsv(buf) ? "text/csv" : null;
}

function looksLikeCsv(buf: Buffer): boolean {
  let text: string;
  try {
    text = new TextDecoder("utf-8", { fatal: true, ignoreBOM: false }).decode(buf);
  } catch {
    return false;
  }
  if (text.charCodeAt(0) === 0xfeff) text = text.slice(1);
  // eslint-disable-next-line no-control-regex
  if (/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(text)) return false;
  const trimmed = text.trimStart();
  if (trimmed.length === 0 || trimmed.startsWith("<")) return false; // empty, or HTML/SVG/XML
  return true;
}

/** Display-safe filename: no path components, control characters or reserved punctuation. */
export function sanitizeFilename(raw: string | undefined): string {
  const base = (raw ?? "").split(/[\\/]/).pop() ?? "";
  // eslint-disable-next-line no-control-regex
  let name = base.replace(/[\u0000-\u001f\u007f"<>:*?|\\/]/g, "_").trim().replace(/^\.+/, "").trim();
  name = [...name].slice(0, 200).join("");
  return name.length > 0 ? name : "statement";
}

/** RFC 6266 attachment header with an ASCII fallback and an RFC 5987 UTF-8 name. */
export function attachmentDisposition(filename: string): string {
  const ascii = filename.replace(/[^\x20-\x7e]/g, "_").replace(/["\\]/g, "_");
  const utf8 = encodeURIComponent(filename).replace(/['()*]/g, (ch) => `%${ch.charCodeAt(0).toString(16).toUpperCase()}`);
  return `attachment; filename="${ascii}"; filename*=UTF-8''${utf8}`;
}

export class VaultStorage {
  private readonly root: string;

  constructor(dir: string) {
    this.root = resolve(dir);
  }

  /** Map a server-generated key to a path inside the root, or throw. */
  private pathFor(key: string): string {
    if (!KEY.test(key)) throw new Error("invalid storage key");
    const p = resolve(this.root, key);
    if (!p.startsWith(this.root + sep)) throw new Error("storage key escapes the vault");
    return p;
  }

  /** Write a new file. Fails if it already exists (keys are unique), never overwrites. */
  async put(key: string, data: Buffer): Promise<void> {
    const p = this.pathFor(key);
    await mkdir(dirname(p), { recursive: true, mode: 0o700 });
    const fh = await open(p, "wx", 0o600);
    try {
      await fh.writeFile(data);
    } finally {
      await fh.close();
    }
  }

  async read(key: string): Promise<{ stream: ReadStream; size: number }> {
    const p = this.pathFor(key);
    const s = await stat(p);
    return { stream: createReadStream(p), size: s.size };
  }

  /** Best-effort removal; a missing file is not an error. */
  async remove(key: string): Promise<void> {
    await rm(this.pathFor(key), { force: true });
  }
}
